56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
69	     * domain containing at least one dot, with no whitespace in any part.
70	     */
71	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
72	
73	    /**
74	     * Common street-type abbreviations expanded during address normalization. Keys are the
75	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
76	     * expanded form it is replaced with.
77	     */
78	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
79	        "ST", "STREET",
80	        "RD", "ROAD",
81	        "AVE", "AVENUE");
82	
83	    private final ClinicService clinicService;
84	
85	    private final OwnerMapper ownerMapper;
86	
87	    private final PetMapper petMapper;
88	
89	    private final VisitMapper visitMapper;
90	
91	    public OwnerRestControllerV1(ClinicService clinicService,
92	                                 OwnerMapper ownerMapper,
93	                                 PetMapper petMapper,
94	                                 VisitMapper visitMapper) {
95	        this.clinicService = clinicService;
96	        this.ownerMapper = ownerMapper;
97	        this.petMapper = petMapper;
98	        this.visitMapper = visitMapper;
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
104	        Collection<Owner> owners;
105	        if (lastName != null) {
106	            owners = this.clinicService.findOwnerByLastName(lastName);
107	        } else {
108	            owners = this.clinicService.findAllOwners();
109	        }
110	        if (owners.isEmpty()) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
119	        Owner owner = this.clinicService.findOwnerById(ownerId);
120	        if (owner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        validateRequiredFields(ownerFieldsDto);
130	        HttpHeaders headers = new HttpHeaders();
131	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
132	        String address = normalizeAddress(ownerFieldsDto.getAddress());
133	        owner.setAddress(address);
134	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
135	            assignHousehold(owner, ownerFieldsDto.getLastName(), address);
136	        } else {
137	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), address);
138	        }
139	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
140	        rejectDuplicateTelephone(telephone);
141	        owner.setTelephone(telephone);
142	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
143	        if (owner.getRegistrationDate() == null) {
144	            owner.setRegistrationDate(LocalDate.now());
145	        }
146	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
147	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
148	        this.clinicService.saveOwner(owner);
149	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
150	        headers.setLocation(UriComponentsBuilder.newInstance()
151	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
152	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
158	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
159	        if (currentOwner == null) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        currentOwner.setAddress(ownerFieldsDto.getAddress());
163	        currentOwner.setCity(ownerFieldsDto.getCity());
164	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
165	        currentOwner.setLastName(ownerFieldsDto.getLastName());
166	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
167	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
168	        this.clinicService.saveOwner(currentOwner);
169	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
170	    }
171	
172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Transactional
174	    @Override
175	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
176	        Owner owner = this.clinicService.findOwnerById(ownerId);
177	        if (owner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        this.clinicService.deleteOwner(owner);
181	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
187	        Owner owner = this.clinicService.findOwnerById(ownerId);
188	        if (owner == null) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        HttpHeaders headers = new HttpHeaders();
192	        Pet pet = petMapper.toPet(petFieldsDto);
193	        owner.setId(ownerId);
194	        pet.setOwner(owner);
195	        pet.getType().setName(null);
196	        this.clinicService.savePet(pet);
197	        PetDto petDto = petMapper.toPetDto(pet);
198	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
199	            .buildAndExpand(pet.getId()).toUri());
200	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
206	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
207	        if (currentOwner != null) {
208	            Pet currentPet = this.clinicService.findPetById(petId);
209	            if (currentPet != null) {
210	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
211	                currentPet.setName(petFieldsDto.getName());
212	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
213	                this.clinicService.savePet(currentPet);
214	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
215	            }
216	        }
217	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
223	        HttpHeaders headers = new HttpHeaders();
224	        Visit visit = visitMapper.toVisit(visitFieldsDto);
225	        Pet pet = new Pet();
226	        pet.setId(petId);
227	        visit.setPet(pet);
228	        this.clinicService.saveVisit(visit);
229	        VisitDto visitDto = visitMapper.toVisitDto(visit);
230	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
231	            .buildAndExpand(visit.getId()).toUri());
232	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
233	    }
234	
235	
236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
239	        Owner owner = this.clinicService.findOwnerById(ownerId);
240	        if (owner != null) {
241	            Pet pet = owner.getPet(petId);
242	            if (pet != null) {
243	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
244	            }
245	        }
246	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
247	    }
248	
249	    /**
250	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
251	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
252	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
253	     *
254	     * @param ownerFieldsDto the submitted owner fields
255	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
256	     *                                     name of every offending field
257	     */
258	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
259	        List<String> missingFields = new ArrayList<>();
260	        if (isBlank(ownerFieldsDto.getFirstName())) {
261	            missingFields.add("firstName");
262	        }
263	        if (isBlank(ownerFieldsDto.getLastName())) {
264	            missingFields.add("lastName");
265	        }
266	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
267	            missingFields.add("address");
268	        }
269	        if (isBlank(ownerFieldsDto.getCity())) {
270	            missingFields.add("city");
271	        }
272	        if (isBlank(ownerFieldsDto.getTelephone())) {
273	            missingFields.add("telephone");
274	        }
275	        if (!missingFields.isEmpty()) {
276	            throw new InvalidOwnerFieldsException(missingFields);
277	        }
278	    }
279	
280	    private boolean isBlank(String value) {
281	        return value == null || value.isBlank();
282	    }
283	
284	    /**
285	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
286	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
287	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
288	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
289	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
290	     *
291	     * @param telephone the raw telephone value submitted by the client
292	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
293	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
294	     *                                     400 response
295	     */
296	    private String normalizeTelephone(String telephone) {
297	        String e164 = toE164(telephone);
298	        if (e164 == null) {
299	            throw new InvalidOwnerFieldsException(List.of("telephone"));
300	        }
301	        return e164;
302	    }
303	
304	    /**
305	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
306	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
307	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
308	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits.
309	     *
310	     * @param telephone the raw telephone value, possibly {@code null}
311	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
312	     */
313	    private String toE164(String telephone) {
314	        if (telephone == null) {
315	            return null;
316	        }
317	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
318	        boolean hasPlus = cleaned.startsWith("+");
319	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
320	        String nationalSignificant = hasPlus
321	            ? digits
322	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
323	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
324	            return null;
325	        }
326	        return "+" + nationalSignificant;
327	    }
328	
329	    /**
330	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
331	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
332	     * returned value is that address lower-cased.
333	     *
334	     * @param email the raw email value submitted by the client, or {@code null} if omitted
335	     * @return the lower-cased email, or {@code null} if none was supplied
336	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
337	     *                                     yielding a 400 response
338	     */
339	    private String normalizeEmail(String email) {
340	        if (email == null) {
341	            return null;
342	        }
343	        if (!EMAIL_PATTERN.matcher(email).matches()) {
344	            throw new InvalidOwnerFieldsException(List.of("email"));
345	        }
346	        return email.toLowerCase(Locale.ROOT);
347	    }
348	
349	    /**
350	     * Counts the existing owners that, before this create, already share the given first name and
351	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
352	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
353	     * been saved yet, so it is never included in the count.
354	     *
355	     * @param firstName the first name of the owner being created
356	     * @param lastName  the last name of the owner being created
357	     * @return the number of existing owners sharing both names
358	     */
359	    private int countNamesakes(String firstName, String lastName) {
360	        String normalizedFirstName = normalizeForComparison(firstName);
361	        String normalizedLastName = normalizeForComparison(lastName);
362	        return (int) this.clinicService.findAllOwners().stream()
363	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
364	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
365	            .count();
366	    }
367	
368	    /**
369	     * Builds the owner's {@code customerCode}, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3}
370	     * is the upper-cased first three letters of the city, {@code LAST3} the upper-cased first three
371	     * letters of the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one
372	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
373	     *
374	     * @param city     the owner's city
375	     * @param lastName the owner's last name
376	     * @return the formatted customer code
377	     */
378	    private String generateCustomerCode(String city, String lastName) {
379	        String city3 = first3Letters(city);
380	        String last3 = first3Letters(lastName);
381	        int sequence = countOwnersInCity(city) + 1;
382	        return String.format("%s-%s-%04d", city3, last3, sequence);
383	    }
384	
385	    /**
386	     * Returns the upper-cased first three letters of the given value, with any non-letter characters
387	     * removed first, used to build the city and last-name segments of a {@code customerCode}.
388	     *
389	     * @param value the value to abbreviate
390	     * @return the upper-cased first three letters, or fewer if the value has fewer letters
391	     */
392	    private String first3Letters(String value) {
393	        String letters = value.replaceAll("[^\\p{L}]", "");
394	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
395	    }
396	
397	    /**
398	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
399	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
400	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
401	     * has not been saved yet, so it is never included in the count.
402	     *
403	     * @param city the city of the owner being created
404	     * @return the number of existing owners in that city
405	     */
406	    private int countOwnersInCity(String city) {
407	        String normalizedCity = normalizeForComparison(city);
408	        return (int) this.clinicService.findAllOwners().stream()
409	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
410	            .count();
411	    }
412	
413	    /**
414	     * Rejects creation of an owner whose E.164 telephone is already used by any other owner. Stored
415	     * telephones are converted to E.164 here as well so the comparison is independent of the format
416	     * each owner was originally saved with; a stored value that cannot form a valid E.164 number is
417	     * ignored rather than matched.
418	     *
419	     * @param telephone the E.164 telephone of the owner being created
420	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone,
421	     *                                          yielding a 409 Conflict response
422	     */
423	    private void rejectDuplicateTelephone(String telephone) {
424	        boolean inUse = this.clinicService.findAllOwners().stream()
425	            .map(Owner::getTelephone)
426	            .map(this::toE164)
427	            .anyMatch(telephone::equals);
428	        if (inUse) {
429	            throw new DuplicateOwnerTelephoneException(telephone);
430	        }
431	    }
432	
433	    /**
434	     * Rejects creation of an owner whose last name and address both match an existing owner's,
435	     * which marks them as belonging to the same household. Both the last name and the address are
436	     * compared case-insensitively with surrounding and internal whitespace collapsed, so values
437	     * that differ only in letter case or spacing are still treated as a match.
438	     *
439	     * @param lastName the last name of the owner being created
440	     * @param address  the address of the owner being created
441	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
442	     *                                          address, yielding a 409 Conflict response
443	     */
444	    private void rejectDuplicateHousehold(String lastName, String address) {
445	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
446	            throw new DuplicateOwnerHouseholdException(lastName, address);
447	        }
448	    }
449	
450	    /**
451	     * Finds every existing owner belonging to the household identified by the given last name and
452	     * address — that is, the owners the duplicate-household rule rejects and the {@code sharesHousehold}
453	     * opt-in joins. Both the last name and the address are compared case-insensitively with surrounding
454	     * and internal whitespace collapsed, so values that differ only in letter case or spacing still
455	     * match. This single definition of household membership is shared by {@link #rejectDuplicateHousehold}
456	     * and {@link #assignHousehold}.
457	     *
458	     * @param lastName the last name of the owner being created
459	     * @param address  the address of the owner being created
460	     * @return the existing owners in that household, or an empty list if there are none
461	     */
462	    private List<Owner> findHouseholdMembers(String lastName, String address) {
463	        String normalizedLastName = normalizeForComparison(lastName);
464	        String normalizedAddress = normalizeAddress(address);
465	        return this.clinicService.findAllOwners().stream()
466	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
467	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
468	            .toList();
469	    }
470	
471	    /**
472	     * Enrolls a newly created owner into the household of any existing owner that shares its last
473	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
474	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
475	     * whitespace. When at least one such owner already exists, every member of the household — the
476	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
477	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
478	     * and address is created and back-filled onto the existing members. When no owner yet lives at
479	     * that address under the same last name no identifier is assigned and the owner is created alone.
480	     *
481	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
482	     * @param lastName the last name of the owner being created
483	     * @param address  the address of the owner being created
484	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
485	     */
486	    private String assignHousehold(Owner newOwner, String lastName, String address) {
487	        List<Owner> members = findHouseholdMembers(lastName, address);
488	        if (members.isEmpty()) {
489	            return null;
490	        }
491	        String householdId = members.stream()
492	            .map(Owner::getHouseholdId)
493	            .filter(existing -> existing != null && !existing.isBlank())
494	            .findFirst()
495	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeAddress(address)));
496	        for (Owner member : members) {
497	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
498	                member.setHouseholdId(householdId);
499	                this.clinicService.saveOwner(member);
500	            }
501	        }
502	        newOwner.setHouseholdId(householdId);
503	        return householdId;
504	    }
505	
506	    /**
507	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
508	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
509	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
510	     * same identifier, so members of one household share a single value.
511	     *
512	     * @param normalizedLastName the household's last name, already normalized for comparison
513	     * @param normalizedAddress  the household's address, already normalized for comparison
514	     * @return the derived household identifier
515	     */
516	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
517	        try {
518	            byte[] digest = MessageDigest.getInstance("SHA-256")
519	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
520	            StringBuilder hex = new StringBuilder(digest.length * 2);
521	            for (byte b : digest) {
522	                hex.append(String.format("%02x", b));
523	            }
524	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
525	        } catch (NoSuchAlgorithmException e) {
526	            throw new IllegalStateException("SHA-256 algorithm not available", e);
527	        }
528	    }
529	
530	    /**
531	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
532	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
533	     * the result is lower-cased.
534	     *
535	     * @param value the value to normalize, possibly {@code null}
536	     * @return the normalized value, or an empty string if {@code value} is {@code null}
537	     */
538	    private String normalizeForComparison(String value) {
539	        if (value == null) {
540	            return "";
541	        }
542	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
543	    }
544	
545	    /**
546	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
547	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
548	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
549	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
550	     * This normalized value is what gets stored and returned, and it is the form every address
551	     * comparison (household duplicate detection and the shared household id) uses.
552	     *
553	     * @param address the raw address value submitted by the client, possibly {@code null}
554	     * @return the normalized address, or an empty string if {@code address} is {@code null}
555	     */
556	    private String normalizeAddress(String address) {
557	        if (address == null) {
558	            return "";
559	        }
560	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
561	        if (collapsed.isEmpty()) {
562	            return collapsed;
563	        }
564	        String[] tokens = collapsed.split(" ");
565	        StringBuilder normalized = new StringBuilder(collapsed.length());
566	        for (int i = 0; i < tokens.length; i++) {
567	            if (i > 0) {
568	                normalized.append(' ');
569	            }
570	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
571	        }
572	        return normalized.toString();
573	    }
574	}
